if __name__=='__main__':
    plan=json.loads(Path(str(PREFIX)+'-plan.json').read_text(encoding='utf-8'))
    assert len(texts)==len(rows)==len(sources)==30
    drafts=[]
    for row,p,text,src in zip(rows,plan['proposals'],texts,sources):
        n=int(p['id']); title,point,tags,compared,reason,subject,concept,keywords=row
        scene='interaction' if n in [1103,1107,1118,1120,1121,1122,1124,1127,1129] else 'diagram' if n in [1125,1131] else 'object'
        illustration=dict(concept=concept,scene_type=scene,primary_subject=subject,secondary_subjects=[],visual_keywords=keywords.split(','),composition_hints=['dominant_central_motif','balanced_transparent_margins'],mood='neutral',palette=['teal_amber','terracotta_cream','indigo_cyan','blue_gold'][n%4])
        content=''.join('<p>'+s+'</p>' for s in text.split('|'))
        assert 500<=len(content)<=1200,(n,len(content))
        drafts.append(dict(id=p['id'],title=title,content=content,category=p['category'],sources=[dict(label=l,url=u) for l,u in src],illustration=illustration,knowledge=p['knowledge']))
    save('-drafts.json',drafts)
    print([(d['id'],len(d['content'])) for d in drafts])
